function findSelectedComboboxItemText(
  children: React.ReactNode,
  selectedValue: string | null,
): string | null {
  if (selectedValue === null) return null;

  let selectedText: string | null = null;

  const visit = (node: React.ReactNode): void => {
    if (selectedText !== null) return;

    React.Children.forEach(node, (child) => {
      if (selectedText !== null || !React.isValidElement(child)) return;

      const childProps = child.props as {
        children?: React.ReactNode;
        label?: unknown;
        textValue?: unknown;
        value?: unknown;
        "aria-label"?: unknown;
      };
      if (childProps.value === selectedValue) {
        selectedText = getSelectedComboboxTextFromProps(childProps);
        return;
      }

      visit(childProps.children);
    });
  };

  visit(children);
  return selectedText;
}

function getSelectedComboboxTextFromProps(props: {
  children?: React.ReactNode;
  label?: unknown;
  textValue?: unknown;
  "aria-label"?: unknown;
}): string | null {
  const explicitText =
    getStringPropText(props.textValue) ??
    getStringPropText(props.label) ??
    getStringPropText(props["aria-label"]);
  if (explicitText !== null) return explicitText;

  const childText =
    getComboboxItemTextFromReactNode(props.children) ?? getTextFromReactNode(props.children).trim();
  return childText.length > 0 ? childText : null;
}

function getComboboxItemTextFromReactNode(node: React.ReactNode): string | null {
  let selectedText: string | null = null;

  const visit = (candidate: React.ReactNode): void => {
    if (selectedText !== null) return;

    React.Children.forEach(candidate, (child) => {
      if (selectedText !== null || !React.isValidElement(child)) return;

      const childProps = child.props as {
        children?: React.ReactNode;
        "data-sw-combobox-item-text"?: unknown;
      };
      if (isComboboxItemTextElement(child)) {
        const text = getTextFromReactNode(childProps.children).trim();
        selectedText = text.length > 0 ? text : null;
        return;
      }

      visit(childProps.children);
    });
  };

  visit(node);
  return selectedText;
}

function getStringPropText(value: unknown): string | null {
  if (typeof value !== "string" && typeof value !== "number") return null;

  const text = String(value).trim();
  return text.length > 0 ? text : null;
}

function isComboboxItemTextElement(node: React.ReactElement): boolean {
  const props = node.props as { "data-sw-combobox-item-text"?: unknown };
  if (props["data-sw-combobox-item-text"] !== undefined) return true;

  const displayName = getReactComponentDisplayName(node.type);
  return displayName === "Combobox.ItemText" || displayName === "ComboboxItemText";
}

function getReactComponentDisplayName(type: unknown): string | null {
  if (typeof type === "string") return null;
  if (typeof type !== "function" && (typeof type !== "object" || type === null)) return null;

  const candidate = type as { displayName?: string; name?: string };
  return candidate.displayName ?? candidate.name ?? null;
}

function getTextFromReactNode(node: React.ReactNode): string {
  if (node === null || node === undefined || typeof node === "boolean") return "";
  if (typeof node === "string" || typeof node === "number") return String(node);
  if (!React.isValidElement(node)) {
    let text = "";
    React.Children.forEach(node, (child) => {
      text += getTextFromReactNode(child);
    });
    return text;
  }

  return getTextFromReactNode((node.props as { children?: React.ReactNode }).children);
}

function getTextFromComboboxItem(item: HTMLElement | undefined): string | null {
  if (!item) return null;

  const textElement = item.querySelector<HTMLElement>("[data-sw-combobox-item-text]");
  const text = (textElement ?? item).textContent?.trim() ?? "";
  return text.length > 0 ? text : null;
}
